var s=`0911-dim-sum-siu-mai`;var n=`world-0911`;var t=`CN`;var o=`east-asia`;var a=8;var r=51;var m={en:`Dim Sum Siu Mai`,ua:`Сіу май`};var u={en:`Dim Sum Siu Mai is a China dish made with ground pork, shrimp, shiitake mushroom, light soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сіу май, страва кухні країни Китай. Основні складники: свинячий фарш, креветка, шиїтаке, світлий соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-pork`,450,`g`],[`shrimp`,240,`g`],[`shiitake-mushroom`,110,`g`],[`light-soy-sauce`,35,`ml`],[`toasted-sesame-oil`,17,`ml`],[`ground-ginger`,14,`g`]]},{en:`Place pork-and-shrimp filling in square wonton wrappers, pleat sides but leave the siu mai tops open.`,ua:`Покладіть свинячо-креветкову начинку на квадратні обгортки вонтонів, зберіть боки складками, але залиште верх сіу май відкритим.`,t:[`rolling-stuffed-food`],m:22,i:[[`wonton-wrappers`,28,`pcs`]]},{en:`Steam the prepared portions in a covered steamer over gently boiling water for about 14 minutes until completely cooked or set, then remove carefully.`,ua:`Готуйте підготовлені порції на парі під кришкою над слабко киплячою водою близько 14 хвилин до повної готовності чи застигання, обережно вийміть.`,t:[`steaming`],m:14,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,35,`g`]]}];var l={slug:s,id:n,country:`CN`,region:o,servings:8,minutes:51,title:m,text:u,steps:g};export{t as country,l as default,n as id,r as minutes,o as region,a as servings,s as slug,g as steps,u as text,m as title};